public static class WorldInfrastructureTests
{
 public static WorldProject Fixture(){var a=MapGenerator.Generate(new(){Kind="blank"});a.WorldX=0;a.WorldY=0;var b=MapGenerator.Generate(new(){Kind="blank"});b.WorldX=1;b.WorldY=0;return new(){Maps=[new(){Project=a},new(){Project=b}]};}
 public static IEnumerable<(string,Action)> Cases(){
  yield return("shared native infrastructure remains structurally editable without an installed game",()=>Temporary(root=>{var world=WorldInfrastructure.Put(Fixture(),new(){Id="offline-bridge",Kind="bridge",Level=2,Width=6,Access="stairs",GuardRails=true,Points=[new(220,100),new(290,100)]});var assets=new GameAssetCatalog(root,Path.Combine(root,"no-game-installed"));Check(!assets.Ready,"Offline fixture unexpectedly found game resources");AssetRules.WorldInfrastructure(world,assets);world.Maps[0].Project.AssetSources[InfrastructureGeometry.DeckTile]="other-provider";Reject(()=>WorldAssembler.Validate(world));}));
  yield return("shared railway checks native sprite providers even without elevated geometry",()=>Temporary(root=>{var world=WorldInfrastructure.Put(Fixture(),new(){Id="tracks",Kind="railway",Width=3,Points=[new(220,70),new(290,70)]});Check(WorldInfrastructure.Build(world).Tiles.Count==0&&WorldInfrastructure.ResourceIds(world).Order().SequenceEqual(new[]{"industry_railroad_01_3","industry_railroad_01_5"}),"Railway resources omitted or wrong axis");var game=Environment.GetEnvironmentVariable("PZMAP_GAME_PATH")??"";if(!Directory.Exists(Path.Combine(game,"media")))return;var folder=Path.Combine(root,"rail-override");Directory.CreateDirectory(Path.Combine(folder,"media"));File.WriteAllText(Path.Combine(folder,"mod.info"),"id=rail-override\nname=Rail override fixture\ntiledef=rail-fixture 912\n");using(var writer=new BinaryWriter(File.Create(Path.Combine(folder,"media","rail-fixture.tiles")),Encoding.Latin1)){void Line(string text){writer.Write(Encoding.Latin1.GetBytes(text));writer.Write((byte)10);}writer.Write("tdef"u8);writer.Write(1);writer.Write(1);Line("industry_railroad_01");Line("fixture.png");writer.Write(6);writer.Write(1);writer.Write(912);writer.Write(6);for(var i=0;i<6;i++){writer.Write(1);Line("solidfloor");Line("");}}var assets=new GameAssetCatalog(root,game);AssetRules.WorldInfrastructure(world,assets);assets.DiscoverMods([root],"42.0.0");assets.ActivateMods(["rail-override"]);Check(assets.Get("industry_railroad_01_3").Source!="game","Override fixture did not replace tracks");Reject(()=>AssetRules.WorldInfrastructure(world,assets));}));
  yield return("shared bridge piers leave a shared world road passable beneath the deck",()=>{var world=WorldInfrastructure.Put(Fixture(),new(){Id="bridge-first",Kind="bridge",Level=2,Width=6,SupportSpacing=12,Points=[new(220,100),new(290,100)]});world=WorldInfrastructure.Put(world,new(){Id="world-road",Kind="road",Width=8,Points=[new(228,70),new(228,130)]});var geometry=WorldInfrastructure.Build(world);Check(!geometry.Tiles.Any(t=>t.X==228&&t.Y==97&&t.Z is 0 or 1&&t.Id.StartsWith("walls_")),"Bridge pier blocks a shared world road");var section=WorldAssembler.ProjectSection(world,world.Maps[0]);Check(section.Terrain[97*256+228]==Terrain.Road&&geometry.Tiles.Any(t=>t.X==228&&t.Y==97&&t.Z==2&&t.Id==InfrastructureGeometry.DeckTile),"Road/deck underpass lost its height separation");});
  yield return("shared paths survive separate section metadata revisions and reject conflicting section saves atomically",()=>Temporary(root=>{
   using var store=new WorldStore(root);var world=WorldInfrastructure.Put(Fixture(),new(){Id="stored",Kind="bridge",Level=2,Width=6,Access="stairs",GuardRails=true,Points=[new(220,100),new(290,100)]});store.SaveAsync(world.Id,world).GetAwaiter().GetResult();var manifest=store.ManifestAsync(world.Id).GetAwaiter().GetResult()!;var snapshot=store.LoadSectionAsync(world.Id,world.Maps[0].Id).GetAwaiter().GetResult();Check(snapshot.Shared.Version==6&&snapshot.Shared.LinearFeatures.Count==1&&snapshot.Member.Project.SharedInfrastructure is null&&snapshot.Member.Project.LinearFeatures.Count==0,"Independent section lost shared metadata or gained projected ownership");
   snapshot.Member.Project.Name="Changed section";var updated=store.SaveSectionAsync(world.Id,snapshot.Member.Id,snapshot.Revision,snapshot.Member.Project).GetAwaiter().GetResult();Check(updated.MetadataHash==manifest.MetadataHash&&updated.Sections[1].Hash==manifest.Sections[1].Hash,"Section edit rewrote shared source or unrelated section");var prior=store.LoadAsync(world.Id,version:1).GetAwaiter().GetResult()!;Check(prior.LinearFeatures.Count==1&&prior.Maps[0].Project.Name!="Changed section","Prior shared-source revision lost");
   var bad=store.LoadSectionAsync(world.Id,snapshot.Member.Id).GetAwaiter().GetResult();bad.Member.Project.Buildings.Add(new(){X=224,Y=97,Width=8,Height=8});ProjectValidator.Validate(bad.Member.Project);Reject(()=>store.SaveSectionAsync(world.Id,bad.Member.Id,bad.Revision,bad.Member.Project).GetAwaiter().GetResult());var after=store.ManifestAsync(world.Id).GetAwaiter().GetResult()!;Check(after.Revision==updated.Revision&&after.Sections[0].Hash==updated.Sections[0].Hash&&after.MetadataHash==updated.MetadataHash,"Rejected collision changed saved revision");
   bad=store.LoadSectionAsync(world.Id,snapshot.Member.Id).GetAwaiter().GetResult();bad.Member.Project.Terrain[108*256+220]=Terrain.Water;ProjectValidator.Validate(bad.Member.Project);Reject(()=>store.SaveSectionAsync(world.Id,bad.Member.Id,bad.Revision,bad.Member.Project).GetAwaiter().GetResult());var full=store.LoadAsync(world.Id).GetAwaiter().GetResult()!;Check(full.Version==6&&full.LinearFeatures.Single().Id=="stored"&&full.Maps[0].Project.Name=="Changed section"&&full.Maps[0].Project.Terrain[108*256+220]==Terrain.Grass,"Failed stair landing edit changed shared world");
  }));
  yield return("browser world publication preserves edits and removal of the authoritative shared path layer",()=>Temporary(root=>{
   var store=new AgentWorldStore(root);var created=store.Create(Fixture());var changed=WorldInfrastructure.Put(created.World,new(){Id="published",Kind="bridge",Level=2,Points=[new(220,100),new(290,100)]});var published=store.Publish(created.Token,created.Revision,changed);var restored=store.Read(created.Token);Check(restored.Revision==2&&restored.World.Version==6&&restored.World.LinearFeatures.Count==1,"Publishing a world dropped shared paths or format");changed.LinearFeatures[0].Points[0]=new(1,1);Check(store.Read(created.Token).World.LinearFeatures[0].Points[0].X==220,"Published world aliased browser source");var removed=WorldInfrastructure.Remove(published.World,"published");store.Publish(created.Token,published.Revision,removed);Check(store.Read(created.Token).World.LinearFeatures.Count==0,"Publishing removal resurrected a shared path");store.Close(created.Token);
  }));
  yield return("OSM preserve reimport retains shared paths in the original world frame without aliasing",()=>Temporary(root=>{
   var bounds=new GeoBounds{West=30,East=30.006,South=50,North=50.002};var world=WorldInfrastructure.Put(Fixture(),new(){Id="reimport",Kind="bridge",Level=2,Points=[new(220,100),new(290,100)]});world.GeoReference=new(){Bounds=bounds,MetresPerTile=1,OriginCellX=0,OriginCellY=0};var source=JsonSerializer.Serialize(world);var assets=new GameAssetCatalog(root,Environment.GetEnvironmentVariable("PZMAP_GAME_PATH")??"");using var client=new OsmClient(Path.Combine(root,"cache"),new EmptyOsmHandler(),TimeSpan.Zero);using var service=new OsmWorldImportService(client,assets,Path.Combine(root,"jobs"));var started=JsonSerializer.SerializeToElement(service.Start(new(bounds,SectionSize:256,OriginCellX:0,OriginCellY:0,ExistingWorld:world,PreserveEdits:true)));var id=started.GetProperty("id").GetString()!;var deadline=DateTime.UtcNow.AddSeconds(20);while(true){var state=JsonSerializer.SerializeToElement(service.Status(id));var status=state.GetProperty("status").GetString();if(status=="completed")break;if(status=="failed"||DateTime.UtcNow>deadline)throw new Exception("OSM preserve job failed: "+state);Thread.Sleep(10);}using var file=File.OpenRead(service.ResultFile(id));var result=JsonSerializer.Deserialize<WorldProject>(file,NativeMapExporter.JsonOptions)!;Check(result.Version==6&&result.LinearFeatures.Count==1&&result.LinearFeatures[0].Points.SequenceEqual(world.LinearFeatures[0].Points),"OSM preserve dropped authoritative shared paths");Check(JsonSerializer.Serialize(world)==source,"OSM preserve changed source world");
  }));

  yield return("shared bridge crosses separate sparse sections without seam caps or terrain ownership",()=>{var w=Fixture();foreach(var m in w.Maps)for(var y=40;y<180;y++)for(var x=0;x<256;x++)if(Math.Abs(m.Project.WorldX*256+x-256)<8)m.Project.Terrain[y*256+x]=Terrain.Water;var before=JsonSerializer.Serialize(w);var n=WorldInfrastructure.Put(w,new(){Id="shared",Kind="bridge",Level=2,Width=6,GuardRails=true,SupportSpacing=12,Access="stairs",Points=[new(220,100),new(290,100)]});Check(JsonSerializer.Serialize(w)==before,"Source mutated");Check(n.Version>=6&&n.LinearFeatures.Count==1&&n.Maps.All(m=>m.Project.LinearFeatures.Count==0),"Shared source duplicated locally");foreach(var m in n.Maps){var p=WorldAssembler.ProjectSection(n,m);var g=InfrastructureGeometry.Build(p);var x=m.Project.WorldX==0?255:0;Check(g.Tiles.Any(t=>t.X==x&&t.Y==100&&t.Z==2&&t.Id==InfrastructureGeometry.DeckTile),"Missing seam deck");Check(!g.Tiles.Any(t=>t.X==x&&t.Y==100&&t.Id.StartsWith("fencing_")),"Internal seam cap");Check(p.Terrain[100*256+x]==Terrain.Water,"Bridge erased water");}var restored=WorldAssembler.Clone(n);Check(restored.LinearFeatures.Count==1&&WorldInfrastructure.Remove(restored,"shared").Maps.All(m=>m.Project.LinearFeatures.Count==0),"Shared save/remove failed");});
  yield return("shared roads project reversibly and sparse gaps reject atomically",()=>{var w=Fixture();var original=JsonSerializer.Serialize(w.Maps);var n=WorldInfrastructure.Put(w,new(){Id="road",Width=6,Points=[new(220,70),new(290,70)]});Check(n.Maps.All(m=>m.Project.Terrain[70*256+(m.Project.WorldX==0?255:0)]==Terrain.Grass),"Ground projection persisted");foreach(var m in n.Maps)Check(WorldAssembler.ProjectSection(n,m).Terrain[70*256+(m.Project.WorldX==0?255:0)]==Terrain.Road,"Ground seam missing");Check(JsonSerializer.Serialize(WorldInfrastructure.Remove(n,"road").Maps)==original,"Removal changed source");w.Maps[1].Project.WorldX=2;var before=JsonSerializer.Serialize(w);Reject(()=>WorldInfrastructure.Put(w,new(){Kind="bridge",Level=1,Width=4,Points=[new(220,70),new(550,70)]}));Check(JsonSerializer.Serialize(w)==before,"Gap rejection mutated world");});
  yield return("shared bridge native independent lot readback survives both section seams",()=>{var w=WorldInfrastructure.Put(Fixture(),new(){Id="native",Kind="bridge",Level=3,Width=6,GuardRails=true,Points=[new(220,100),new(290,100)]});using var zip=new ZipArchive(new MemoryStream(NativeWorldExporter.Export(w)));foreach(var x in new[]{255,256}){var square=ReadSquare(zip,x,100,3);Check(square.Contains(InfrastructureGeometry.DeckTile),"LOT lost seam deck");Check(!square.Any(t=>t.StartsWith("fencing_")),"LOT seam capped");}using var source=zip.Entries.Single(e=>e.FullName.EndsWith("/world.pzworld.json")).Open();var roundtrip=JsonSerializer.Deserialize<WorldProject>(source,NativeMapExporter.JsonOptions)!;Check(roundtrip.LinearFeatures.Count==1&&roundtrip.Maps.All(m=>m.Project.LinearFeatures.Count==0),"LOT archive duplicated ownership");});
  yield return("shared stairs validate dry land and section movement preserves coverage",()=>{var w=Fixture();w.Maps[0].Project.Terrain[108*256+220]=Terrain.Water;Reject(()=>WorldInfrastructure.Put(w,new(){Kind="bridge",Level=2,Access="stairs",Points=[new(220,100),new(290,100)]}));var n=WorldInfrastructure.Put(Fixture(),new(){Kind="bridge",Level=-2,Access="stairs",GuardRails=true,Points=[new(220,100),new(290,100)]});Check(WorldInfrastructure.Build(n).Tiles.Count(t=>t.Id.StartsWith("carpentry_02_9"))==6,"Wrong stair pieces");Reject(()=>WorldAssembler.Move(n,n.Maps[1].Id,2,0));});
 }
 static void Temporary(Action<string> run){var taskBase=Path.GetFullPath(Path.Combine(Environment.GetEnvironmentVariable("PZMAP_WORKSPACE")??Directory.GetCurrentDirectory(),"work","world-infrastructure-tests"));var path=Path.GetFullPath(Path.Combine(taskBase,Guid.NewGuid().ToString("N")));if(!path.StartsWith(taskBase+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Unsafe test directory");Directory.CreateDirectory(path);try{run(path);}finally{Directory.Delete(path,true);}}
 sealed class EmptyOsmHandler:HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("{\"elements\":[]}")});}
 static List<string> ReadSquare(ZipArchive zip,int x,int y,int z){using var h=new BinaryReader(zip.Entries.Single(e=>e.FullName.EndsWith($"/{x/256}_{y/256}.lotheader")).Open());Check(new string(h.ReadChars(4))=="LOTH"&&h.ReadInt32()==1,"Header");var tiles=Enumerable.Range(0,h.ReadInt32()).Select(_=>Line(h)).ToArray();Check(h.ReadInt32()==8&&h.ReadInt32()==8,"Chunk dimensions");var min=h.ReadInt32();var max=h.ReadInt32();Check(z>=min&&z<=max,"Floor range");using var stream=new MemoryStream();using(var input=zip.Entries.Single(e=>e.FullName.EndsWith($"/world_{x/256}_{y/256}.lotpack")).Open())input.CopyTo(stream);stream.Position=0;using var r=new BinaryReader(stream);Check(new string(r.ReadChars(4))=="LOTP"&&r.ReadInt32()==1&&r.ReadInt32()==1024,"Pack");var offsets=Enumerable.Range(0,1024).Select(_=>r.ReadInt64()).ToArray();stream.Position=offsets[(x%256/8)*32+y%256/8];var target=(z-min)*64+x%8*8+y%8;var at=0;while(at<=target){var count=r.ReadInt32();if(count==-1){at+=r.ReadInt32();if(at>target)return [];continue;}r.ReadInt32();var result=Enumerable.Range(1,count-1).Select(_=>tiles[r.ReadInt32()]).ToList();if(at++==target)return result;}return [];}
 static string Line(BinaryReader r){var bytes=new List<byte>();byte b;while((b=r.ReadByte())!=10)bytes.Add(b);return Encoding.ASCII.GetString(bytes.ToArray());}
 static void Check(bool value,string message){if(!value)throw new Exception(message);}static void Reject(Action action){try{action();}catch(ArgumentException){return;}throw new Exception("Expected validation failure");}
}
